-- SB-84: removing a member from a household. See "Removing a member" in
-- ../README.md.
--
-- The first statements are generated by drizzle-kit: the `removed_at` column,
-- the managed-is-kid check relaxed for removed rows, the new
-- `household_members_removed_detached_check` (a removed row has no login), and
-- the update policy refusing removed rows. The rest is hand-written, because
-- drizzle-kit doesn't manage functions:
--
-- - The RLS helpers from 0000 and 0003 ignore removed members. Removal clears
--   `user_id`, so the ones that go by the signed-in user would never find a
--   removed row anyway; the explicit filter keeps that true if it ever
--   changes. `is_member_id_in` and `can_act_as_member` are the ones it really
--   changes: nothing new can point at a removed member, and nobody can act as
--   a removed managed kid. CREATE OR REPLACE keeps their grants.
-- - app.check_chore_rotation (0009) treats a removed member like one who left
--   the household: taking them out of a rotation never fails its commit-time
--   check.
-- - app.accept_household_invite and app.merge_household_via_invite (0023)
--   don't count removed kids towards the 12-kid cap, and a merge doesn't bring
--   removed members (or their balances) along. Otherwise unchanged.
-- - app.remove_household_member(member, move_points_to, acting_as): new,
--   granted to authenticated_backend.
--
-- HINTs raised by app.remove_household_member, matched by the web app:
--   not-signed-in      no JWT claims (42501)
--   member-not-found   no such member, already removed, or the caller isn't in
--                      its household (P0002; not told apart)
--   not-parent         the caller is a kid there (42501)
--   kid-profile        `acting_as` is a kid profile, not the caller (42501)
--   self               the caller named themselves (22023)
--   not-owner          a parent removing a parent or owner (42501)
--   last-owner         the household's only owner (22023)
--   invalid-recipient  `move_points_to` isn't another current kid in the
--                      household, or the member being removed isn't a kid
--                      (22023)

ALTER TABLE "household_members" DROP CONSTRAINT "household_members_managed_is_kid_check";--> statement-breakpoint
ALTER TABLE "household_members" ADD COLUMN "removed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "household_members" ADD CONSTRAINT "household_members_removed_detached_check" CHECK ("household_members"."removed_at" is null or "household_members"."user_id" is null);--> statement-breakpoint
ALTER TABLE "household_members" ADD CONSTRAINT "household_members_managed_is_kid_check" CHECK ("household_members"."user_id" is not null or "household_members"."role" = 'kid' or "household_members"."removed_at" is not null);--> statement-breakpoint
ALTER POLICY "household_members_update" ON "household_members" TO authenticated_backend USING ("household_members"."removed_at" is null and (app.is_household_owner("household_members"."household_id")
				or (app.is_household_parent("household_members"."household_id") and ("household_members"."role" = 'kid' or "household_members"."user_id" = (select app.current_user_id()))))) WITH CHECK (app.is_household_owner("household_members"."household_id")
				or (app.is_household_parent("household_members"."household_id") and ("household_members"."role" = 'kid' or ("household_members"."user_id" = (select app.current_user_id()) and "household_members"."role" = 'parent'))));--> statement-breakpoint

CREATE OR REPLACE FUNCTION app.is_member_of(household uuid, member uuid) RETURNS boolean
	LANGUAGE plpgsql STABLE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	BEGIN
		RETURN EXISTS (
			SELECT 1 FROM public.household_members m
			WHERE m.household_id = household AND m.user_id = member
				AND m.removed_at IS NULL
		);
	END
	$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.is_household_owner(household uuid) RETURNS boolean
	LANGUAGE plpgsql STABLE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	BEGIN
		RETURN EXISTS (
			SELECT 1 FROM public.household_members m
			WHERE m.household_id = household
				AND m.user_id = app.current_user_id()
				AND m.role = 'owner'
				AND m.removed_at IS NULL
		);
	END
	$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.current_member_id(household uuid) RETURNS uuid
	LANGUAGE plpgsql STABLE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	BEGIN
		RETURN (
			SELECT m.id FROM public.household_members m
			WHERE m.household_id = household AND m.user_id = app.current_user_id()
				AND m.removed_at IS NULL
		);
	END
	$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.is_household_parent(household uuid) RETURNS boolean
	LANGUAGE plpgsql STABLE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	BEGIN
		RETURN EXISTS (
			SELECT 1 FROM public.household_members m
			WHERE m.household_id = household
				AND m.user_id = app.current_user_id()
				AND m.role::text IN ('owner', 'parent')
				AND m.removed_at IS NULL
		);
	END
	$$;
--> statement-breakpoint
-- A removed member isn't "in" the household any more: nothing new (a chore
-- assignment, a rotation slot, a ledger row, a favour's doer) can point at them.
CREATE OR REPLACE FUNCTION app.is_member_id_in(household uuid, member uuid) RETURNS boolean
	LANGUAGE plpgsql STABLE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	BEGIN
		RETURN EXISTS (
			SELECT 1 FROM public.household_members m
			WHERE m.id = member AND m.household_id = household
				AND m.removed_at IS NULL
		);
	END
	$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.is_own_member(member uuid) RETURNS boolean
	LANGUAGE plpgsql STABLE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	BEGIN
		RETURN EXISTS (
			SELECT 1 FROM public.household_members m
			WHERE m.id = member AND m.user_id = app.current_user_id()
				AND m.removed_at IS NULL
		);
	END
	$$;
